$b64=''
[IO.File]::WriteAllBytes('C:\SteveDesktop\diag\compact_wsl_vhdx.ps1',[Convert]::FromBase64String($b64))
$a=New-ScheduledTaskAction -Execute 'powershell.exe' -Argument '-NoProfile -ExecutionPolicy Bypass -File C:\SteveDesktop\diag\compact_wsl_vhdx.ps1'
Register-ScheduledTask -TaskName RM_CompactWslVhdx -Action $a -User SYSTEM -RunLevel Highest -Force | Out-Null
